package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.*;
@Entity @Table(name="spms_indicator_dimension_level",uniqueConstraints=@UniqueConstraint(name="uk_spms_indicator_dimension_band",columnNames={"agency_id","dimension_id","rating_band_id"}))
public class PerformanceIndicatorDimensionLevel extends RspAuditedEntity{public enum Operator{LT,LTE,EQ,GTE,GT,BETWEEN,MANUAL_CRITERIA}@Column(name="dimension_id",nullable=false,length=36)private String dimensionId;@Column(name="rating_band_id",nullable=false,length=36)private String ratingBandId;@Enumerated(EnumType.STRING)@Column(name="comparison_operator",nullable=false,length=30)private Operator operator;@Column(name="threshold_from",precision=19,scale=6)private BigDecimal thresholdFrom;@Column(name="threshold_to",precision=19,scale=6)private BigDecimal thresholdTo;@Column(name="manual_criteria",length=2000)private String manualCriteria;protected PerformanceIndicatorDimensionLevel(){}public PerformanceIndicatorDimensionLevel(String a,String d,String b,Operator o,BigDecimal from,BigDecimal to,String manual){super(a);dimensionId=requiredText(d,"dimensionId");ratingBandId=requiredText(b,"ratingBandId");operator=o;thresholdFrom=from;thresholdTo=to;manualCriteria=optionalText(manual);if(o==Operator.MANUAL_CRITERIA&&manualCriteria==null)throw new IllegalArgumentException("manualCriteria is required");if(o!=Operator.MANUAL_CRITERIA&&from==null)throw new IllegalArgumentException("thresholdFrom is required");if(o==Operator.BETWEEN&&(to==null||to.compareTo(from)<0))throw new IllegalArgumentException("BETWEEN requires an ordered threshold range");}public String getDimensionId(){return dimensionId;}public String getRatingBandId(){return ratingBandId;}public Operator getOperator(){return operator;}public BigDecimal getThresholdFrom(){return thresholdFrom;}public BigDecimal getThresholdTo(){return thresholdTo;}public String getManualCriteria(){return manualCriteria;}}
